// Exam prep on the study home: a course's exam date and topics -> a countdown and a plan made only from the
// student's own records in that course (lectures without study material, missed quiz questions, flashcards due,
// quizzes not taken yet) and, for each topic they listed, the lectures in the course that mention it (library
// search). Nothing is generated by AI here and nothing is estimated: no readiness scores, no invented weak spots.
import { supabase } from '../lib/supabase.js';
import { searchLibrary, setCourseExam, courseLectureIds } from '../lib/library.js';
import { makeDialog } from '../library/dialogs.js';
import { readSrs, dueIndexes } from '../insights/srs.js';

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const STUDY_KINDS = new Set(['flashcards', 'quiz', 'study_guide', 'exam_points', 'definitions']);
const lectureUrl = (id, tool) => `/transcript?id=${encodeURIComponent(id)}${tool ? `&tab=create&tool=${tool}` : ''}`;

// whole days from today (the student's own calendar) to a 'YYYY-MM-DD' date
export function daysUntil(iso, now = new Date()) {
  const [y, m, d] = String(iso).split('-').map(Number);
  return Math.round((new Date(y, m - 1, d) - new Date(now.getFullYear(), now.getMonth(), now.getDate())) / 86_400_000);
}
export const fmtExamDate = (iso) => { const [y, m, d] = iso.split('-').map(Number); return new Date(y, m - 1, d).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' }); };
export const inDays = (n) => (n === 0 ? 'today' : n === 1 ? 'tomorrow' : `in ${n} days`);

// "cell biology, mitosis; Krebs cycle" -> ['cell biology', 'mitosis', 'Krebs cycle'] (max 10, no repeats)
export function parseTopics(text) {
  const seen = new Set();
  return String(text || '').split(/[\n,;]+/).map((t) => t.trim().slice(0, 80)).filter((t) => {
    const k = t.toLowerCase();
    if (t.length < 2 || seen.has(k)) return false;
    seen.add(k);
    return true;
  }).slice(0, 10);
}

// lectures: [{ id, title, kinds:Set, missed, hasQuiz, quizTaken, due }] -> ordered steps, each tied to a lecture
export function buildPlan(lectures) {
  const steps = [];
  for (const l of lectures) if (![...l.kinds].some((k) => STUDY_KINDS.has(k))) steps.push({ lecture: l, text: 'Make flashcards or a practice quiz', tool: null, why: 'No study material yet' });
  for (const l of lectures) if (l.missed) steps.push({ lecture: l, text: `Retake ${l.missed} missed question${l.missed === 1 ? '' : 's'}`, tool: 'quiz', why: 'From your last quiz' });
  for (const l of lectures) if (l.due) steps.push({ lecture: l, text: `Review ${l.due} flashcard${l.due === 1 ? '' : 's'}`, tool: 'flashcards', why: 'Due in your spaced review' });
  for (const l of lectures) if (l.hasQuiz && !l.quizTaken) steps.push({ lecture: l, text: 'Take the practice quiz', tool: 'quiz', why: 'Made, not taken yet' });
  return steps;
}

// a pace that leaves the last day before the exam free for a final look-over; null when it wouldn't help
export function pace(steps, days) {
  if (!steps || days < 2) return null;
  return Math.ceil(steps / (days - 1));
}

async function loadCourse(courseId) {
  const ids = await courseLectureIds(courseId);
  if (!ids.length) return [];
  const [t, arts, ins] = await Promise.all([
    supabase.from('transcriptions').select('id, title').in('id', ids),
    supabase.from('transcription_artifacts').select('transcription_id, kind, progress').in('transcription_id', ids).eq('status', 'ready'),
    supabase.from('transcription_insights').select('transcription_id, kind').in('transcription_id', ids).eq('status', 'ready'),
  ]);
  const by = new Map((t.data || []).map((r) => [r.id, { id: r.id, title: r.title, kinds: new Set(), missed: 0, hasQuiz: false, quizTaken: false, due: 0 }]));
  for (const r of ins.data || []) by.get(r.transcription_id)?.kinds.add(r.kind);
  for (const a of arts.data || []) {
    const l = by.get(a.transcription_id);
    if (!l) continue;
    l.kinds.add(a.kind);
    if (a.kind === 'quiz') {
      l.hasQuiz = true;
      if (a.progress?.last_score != null) l.quizTaken = true;
      if (Array.isArray(a.progress?.missed)) l.missed += a.progress.missed.length;
    }
    if (a.kind === 'flashcards') l.due += dueIndexes(readSrs(a.progress), Infinity).length;
  }
  return ids.map((id) => by.get(id)).filter(Boolean); // the course's order; recordings deleted since are skipped
}

// for each topic: the course's lectures whose transcript, title or notes mention it
async function coverage(topics, lectures) {
  const inCourse = new Map(lectures.map((l) => [l.id, l]));
  return Promise.all(topics.map(async (topic) => {
    try {
      const hits = (await searchLibrary(topic, { limit: 50 })).filter((h) => inCourse.has(h.transcription_id));
      return { topic, hits: hits.map((h) => ({ lecture: inCourse.get(h.transcription_id), count: h.match_count || 0 })) };
    } catch { return { topic, hits: null }; }
  }));
}

// The exam card for one course. `exam` = { date, topics }.
export async function renderExamCard(el, course, exam, { onEdit }) {
  const days = daysUntil(exam.date);
  el.innerHTML = `<div class="dash-row-head"><h2 class="dash-h" id="dashExamTitle">Exam prep</h2><button type="button" class="dash-all link-btn" data-act="edit-exam">Edit exam</button></div>
    <p class="exam-when"><b>${esc(course.name)}</b> exam <span class="exam-days">${inDays(days)}</span><small>${esc(fmtExamDate(exam.date))}</small></p>
    <div class="exam-body" aria-busy="true"><p class="dash-quiet">Looking at your lectures in this course…</p></div>`;
  el.querySelector('[data-act="edit-exam"]').addEventListener('click', onEdit);
  const body = el.querySelector('.exam-body');
  let lectures;
  try { lectures = await loadCourse(course.id); } catch {
    body.innerHTML = '<p class="dash-error">We couldn’t load this course just now.</p>';
    body.removeAttribute('aria-busy');
    return;
  }
  if (!lectures.length) {
    body.innerHTML = `<p class="dash-quiet">This course has no lectures yet. Add lectures to it from <a href="/library">My Library</a> (a lecture’s ⋯ menu → Courses) and your plan appears here.</p>`;
    body.removeAttribute('aria-busy');
    return;
  }
  const steps = buildPlan(lectures);
  const perDay = pace(steps.length, days);
  const topics = parseTopics(exam.topics);
  const shown = steps.slice(0, 6);
  body.innerHTML = `
    <h3 class="exam-sub">Your plan</h3>
    ${steps.length ? `<p class="exam-pace">${steps.length} step${steps.length === 1 ? '' : 's'} across ${lectures.length} lecture${lectures.length === 1 ? '' : 's'}${perDay ? `. About ${perDay} a day leaves the day before the exam for a last look over your notes.` : '.'}</p>
      <ol class="exam-steps">${shown.map((s) => `<li><a href="${lectureUrl(s.lecture.id, s.tool)}"><b>${esc(s.text)}</b><span>${esc(s.lecture.title)}</span><small>${esc(s.why)}</small></a></li>`).join('')}</ol>
      ${steps.length > shown.length ? `<p class="dash-quiet">${steps.length - shown.length} more after these.</p>` : ''}`
      : `<p class="exam-pace">Every lecture in this course has study material, nothing is due and no missed questions are waiting. Retake a quiz closer to the exam to check what stuck.</p>`}
    ${topics.length ? `<h3 class="exam-sub">Topics you listed</h3><ul class="exam-topics" aria-busy="true">${topics.map((t) => `<li><b>${esc(t)}</b><span class="dash-quiet">Checking…</span></li>`).join('')}</ul>` : ''}`;
  body.removeAttribute('aria-busy');
  if (!topics.length) return;
  const cov = await coverage(topics, lectures);
  const list = body.querySelector('.exam-topics');
  list.innerHTML = cov.map(({ topic, hits }) => `<li><b>${esc(topic)}</b>${hits == null ? '<span class="dash-quiet">Couldn’t check this one.</span>'
    : hits.length ? `<span>Mentioned in ${hits.slice(0, 3).map((h) => `<a href="${lectureUrl(h.lecture.id)}">${esc(h.lecture.title)}</a>`).join(', ')}${hits.length > 3 ? ` and ${hits.length - 3} more` : ''}</span>`
    : '<span class="exam-gap">Not found in this course’s lectures. It may be worded differently, or in a lecture you haven’t added.</span>'}</li>`).join('');
  list.removeAttribute('aria-busy');
}

// the exam dialog: date + topics; resolves true when saved or removed
export function examDialog(course, exam) {
  return new Promise((resolve) => {
    let done = false;
    const finish = (v) => { if (!done) { done = true; resolve(v); } };
    const today = new Date();
    const min = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
    const { dlg, dismiss } = makeDialog('prompt-dlg exam-dlg', `
      <form class="dlg-form" novalidate>
        <h3>${exam?.date ? 'Edit exam' : 'Add an exam'} · ${esc(course.name)}</h3>
        <label class="dlg-field"><span>Exam date</span><input type="date" name="date" min="${min}" max="2100-12-31" value="${esc(exam?.date || '')}" required /></label>
        <label class="dlg-field"><span>Topics it covers <small>(optional, separated by commas or lines)</small></span>
          <textarea name="topics" rows="4" maxlength="1000" placeholder="e.g. cell membranes, mitosis, the Krebs cycle">${esc(exam?.topics || '')}</textarea></label>
        <p class="dlg-hint">We’ll check which of your lectures in this course mention each topic.</p>
        <p class="dlg-err" role="alert" hidden></p>
        <div class="confirm-actions">
          ${exam?.date ? '<button class="btn btn-ghost exam-remove" type="button" data-act="remove">Remove exam</button>' : ''}
          <button class="btn btn-ghost" type="button" data-act="cancel">Cancel</button>
          <button class="btn btn-primary" type="submit">Save</button>
        </div>
      </form>`, () => finish(false));
    const form = dlg.querySelector('form');
    const err = dlg.querySelector('.dlg-err');
    const fail = (m) => { err.textContent = m; err.hidden = false; form.querySelectorAll('button').forEach((b) => { b.disabled = false; }); };
    const save = async (value) => {
      form.querySelectorAll('button').forEach((b) => { b.disabled = true; });
      try { await setCourseExam(course.id, value); } catch (e) { return fail(e?.message || 'Couldn’t save the exam.'); }
      finish(true);
      dismiss();
    };
    dlg.querySelector('[data-act=cancel]').addEventListener('click', dismiss);
    dlg.querySelector('[data-act=remove]')?.addEventListener('click', () => save({ date: null, topics: '' }));
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const date = form.elements.date.value;
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return fail('Pick the exam date.');
      if (daysUntil(date) < 0) return fail('That date has passed. Pick the date of your next exam.');
      save({ date, topics: form.elements.topics.value });
    });
    form.elements.date.focus();
  });
}
